patch:
diff --git a/tests/repro-19637/repro.js b/tests/repro-19637/repro.js
new file mode 100644
index 0000000..fee9387
--- /dev/null
+++ b/tests/repro-19637/repro.js
@@ -0,0 +1,23 @@
+"use strict";
+const path = require("node:path");
+const eslintPath = process.argv[2] ? path.resolve(process.argv[2]) : path.resolve(__dirname, "../..");
+const { Linter } = require(path.join(eslintPath, "lib/api.js"));
+const { version } = require(path.join(eslintPath, "package.json"));
+
+const code = `'use strict';
+function f() {
+  'use strict';
+  return 1;
+}
+`;
+const linter = new Linter();
+let failed = false;
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const messages = linter.verify(code, {
+		languageOptions: { ecmaVersion, sourceType: "script" },
+		rules: { "no-unused-expressions": ["error", { allowShortCircuit: true, allowTernary: true, allowTaggedTemplates: true }] },
+	});
+	if (messages.length) failed = true;
+	console.log(`eslint ${version} ecmaVersion=${ecmaVersion}:`, messages.length ? messages.map(m => `${m.line}:${m.column} ${m.ruleId} ${m.message}`) : "no errors");
+}
+process.exitCode = failed ? 1 : 0;
